/**
 * Decide whether a given file is "generated" (regenerated by a build step,
 * unsafe to write variants into) or "source" (safe to edit, changes persist).
 *
 * Why this matters: when the user picks an element on a page whose underlying
 * file is regenerated by a build step (e.g. `scripts/build-sub-pages.js`
 * rewriting `public/docs/*.html`), writing variants or accepted changes into
 * that file is silent data loss — the next build wipes them.
 *
 * Signals, in order of reliability:
 *   1. Git check-ignore: gitignored files are assumed generated.
 *   2. File-header markers ("GENERATED", "DO NOT EDIT", "AUTO-GENERATED")
 *      within the first ~300 characters — catches non-git projects.
 */

import { execFileSync, execSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';

const HEADER_SCAN_BYTES = 300;
const HEADER_MARKERS = [
  /@generated\b/i,
  /\bGENERATED\s+FILE\b/,
  /\bAUTO-?GENERATED\b/i,
  /\bDO\s+NOT\s+EDIT\b/i,
];

/**
 * @param {string} filePath - absolute or cwd-relative path
 * @param {object} [options]
 * @param {string} [options.cwd] - project root (defaults to process.cwd())
 */
export function isGeneratedFile(filePath, options = {}) {
  const cwd = options.cwd || process.cwd();
  const absPath = path.isAbsolute(filePath) ? filePath : path.resolve(cwd, filePath);

  if (isGitIgnored(absPath, cwd)) return true;
  if (hasGeneratedHeader(absPath)) return true;
  return false;
}

/**
 * Which of `filePaths` are generated, decided by the same two signals
 * {@link isGeneratedFile} reads and in the same order.
 *
 * The batched form exists for the callers that ask about a whole directory
 * walk. Git answers about every path handed to it in one invocation, so the
 * subprocess cost is paid once for the walk rather than once per file; the
 * answer for any one path is the answer {@link isGeneratedFile} gives it.
 *
 * @param {readonly string[]} filePaths - absolute or cwd-relative paths
 * @param {object} [options]
 * @param {string} [options.cwd] - project root (defaults to process.cwd())
 * @returns {Set<string>} the members of `filePaths` that are generated
 */
export function generatedFilesAmong(filePaths, options = {}) {
  const cwd = options.cwd || process.cwd();
  /** @type {Map<string, string>} */
  const byAbsolute = new Map();
  for (const filePath of filePaths) {
    byAbsolute.set(path.isAbsolute(filePath) ? filePath : path.resolve(cwd, filePath), filePath);
  }
  /** @type {Set<string>} */
  const generated = new Set();
  for (const absPath of gitIgnoredAmong([...byAbsolute.keys()], cwd)) {
    generated.add(/** @type {string} */ (byAbsolute.get(absPath)));
  }
  for (const [absPath, given] of byAbsolute) {
    if (!generated.has(given) && hasGeneratedHeader(absPath)) generated.add(given);
  }
  return generated;
}

/**
 * The git-ignored members of `absPaths`, asked in one invocation.
 *
 * `-z` is what makes the answer readable: git echoes each ignored path back
 * verbatim, and a NUL separator is the one byte a path cannot hold. An
 * invocation that fails for any reason other than "nothing matched" leaves
 * every path un-ignored, which is the same fallback the single-path form takes
 * outside a work tree.
 *
 * @param {readonly string[]} absPaths
 * @param {string} cwd
 * @returns {string[]}
 */
function gitIgnoredAmong(absPaths, cwd) {
  if (absPaths.length === 0) return [];
  /** @type {string} */
  let stdout;
  try {
    stdout = execFileSync('git', ['check-ignore', '-z', '--stdin'], {
      cwd,
      input: absPaths.join('\0') + '\0',
      encoding: 'utf-8',
      stdio: ['pipe', 'pipe', 'ignore'],
      maxBuffer: Infinity,
    });
  } catch (err) {
    // Exit code 1 = no path matched, and git still wrote whatever did. Anything
    // else = not a git repo, or a path outside the work tree: nothing is known
    // to be ignored.
    const status = /** @type {{ status?: number, stdout?: string }} */ (err).status;
    if (status !== 1) return [];
    stdout = /** @type {{ stdout?: string }} */ (err).stdout ?? '';
  }
  return stdout.split('\0').filter((line) => line !== '');
}

/**
 * @param {string} absPath
 * @param {string} cwd
 */
function isGitIgnored(absPath, cwd) {
  try {
    execSync(`git check-ignore --quiet ${JSON.stringify(absPath)}`, {
      cwd,
      stdio: 'ignore',
    });
    return true; // exit 0 = ignored
  } catch (err) {
    // Exit code 1 = not ignored. Exit code 128 = not a git repo or other error.
    // In both cases, treat as "not known to be ignored."
    return false;
  }
}

/** @param {string} absPath */
function hasGeneratedHeader(absPath) {
  let fd;
  try {
    fd = fs.openSync(absPath, 'r');
    const buf = Buffer.alloc(HEADER_SCAN_BYTES);
    const bytesRead = fs.readSync(fd, buf, 0, HEADER_SCAN_BYTES, 0);
    const head = buf.slice(0, bytesRead).toString('utf-8');
    return HEADER_MARKERS.some((re) => re.test(head));
  } catch {
    return false;
  } finally {
    if (fd !== undefined) { try { fs.closeSync(fd); } catch {} }
  }
}
